function report(rows, threshold){
  // rows: [{customer, amount}]
  // intent: keep customers whose TOTAL amount > threshold
  const kept = rows.filter(r => r.amount > threshold); // filter first
  const totals = new Map();
  for (const r of kept){ totals.set(r.customer, (totals.get(r.customer)||0) + r.amount); }
  return [...totals.entries()].map(([c,t]) => ({customer:c, total:t})).sort((a,b)=>a.customer<b.customer?-1:1);
}
this.report = report;

